        dq = deque()
        for i in range(n):
            v = C[i]
            while dq and C[dq[-1]] >= v:
                dq.pop()
            dq.append(i)

            start = i - k + 1
            if start >= 0:
                while dq and dq[0] < start:
                    dq.popleft()
                right[start] = C[dq[0]]

        dq.clear()
        max_center = n - k

        for i in range(n):
            v = B[i]
            while dq and B[dq[-1]] >= v:
                dq.pop()
            dq.append(i)

            start = i - k + 1
            if start < 0:
