        MOD = 10**9 + 7

        first = {}
        last = {}

        for i, num in enumerate(nums):
            if num not in first:
                first[num] = i
            last[num] = i

        intervals = []
        for num in first:
            if first[num] < last[num]:
                intervals.append((first[num], last[num]))

        intervals.sort()

        forbidden_cuts = 0

        if intervals:
            cur_start, cur_end = intervals[0]

            for start, end in intervals[1:]:
                if start > cur_end:
                    forbidden_cuts += cur_end - cur_start
                    cur_start, cur_end = start, end
                else:
                    cur_end = max(cur_end, end)

            forbidden_cuts += cur_end - cur_start

